/**
	* ItemsPanel Component
	*
	* @props value (optional): Array of items (used when attributes is not provided) (Array)
	* @props onChange (optional): (Function)
	* @props attributes (optional): Block attributes (Object)
	* @props setAttributes (optional): (Function)
	* @props clientId (optional): The block client ID (String)
	* @props arrKey (optional): Attribute key holding the items array (String)
	* @props newItem (optional): Template for a new item (Object)
	* @props ItemSettings (optional): Component to render each item's settings (Component)
	* @props itemLabel (optional): 'Item' (String)
	* @props activeIndex (optional): Currently active item index (Number)
	* @props setActiveIndex (optional): (Function)
	* @props design (optional): 'single' | 'all' (String)
	* @props title (optional): '' (String)
	* @props premiumProps (optional): Props for premium features (Object)
	* @props minItem (optional): 1 (Number)
	* @props handleCopy (optional): (Function)
	* @props handleDelete (optional): (Function)
	* @props handleAdd (optional): (Function)
	*/

import { Button, Dashicon, Flex, PanelBody, PanelRow } from '@wordpress/components';
import { __, sprintf } from '@wordpress/i18n';

import { copyIcon } from '../../utils/icons';
import Sortable from './Sortable';

const ItemsPanel = (properties) => {
	const { value, onChange, attributes, setAttributes, clientId, arrKey, newItem, ItemSettings, itemLabel = __('Item'), activeIndex, setActiveIndex, design = 'single', title = '', premiumProps, minItem = 1, handleCopy, handleDelete, handleAdd, ...restProps } = properties;
	const items = attributes ? attributes[arrKey] : value;
	const addNewItem = () => {
		const newValue = [...items, newItem];
		if (typeof handleAdd === 'function') {
			handleAdd(newValue);
			return;
		}
		attributes ? setAttributes({ [arrKey]: newValue }) : onChange(newValue);

		setActiveIndex && setActiveIndex(items.length);
	};

	const duplicateItem = (e, index) => {
		e.preventDefault();
		if (typeof handleCopy === 'function') {
			handleCopy(index);
			return;
		}

		const newValue = [...items.slice(0, index), { ...items[index] }, ...items.slice(index)];

		attributes ? setAttributes({ [arrKey]: newValue }) : onChange(newValue);

		setActiveIndex && setActiveIndex(index + 1);
	}

	const removeItem = (e, index) => {
		e.preventDefault();
		if (typeof handleDelete === 'function') {
			handleDelete(index);
			return;
		}

		const newValue = [...items.slice(0, index), ...items.slice(index + 1)];

		attributes ? setAttributes({ [arrKey]: newValue }) : onChange(newValue);

		setActiveIndex && setActiveIndex(0 === index ? 0 : index - 1);
	}

	const props = { value, onChange, attributes, setAttributes, clientId, arrKey, ItemSettings, removeItem, duplicateItem, itemLabel, activeIndex, setActiveIndex, premiumProps, title, minItem, ...restProps }

	const itemProps = { value, onChange, attributes, setAttributes, clientId, arrKey, setActiveIndex, premiumProps }

	return <>
		{'single' === design && undefined !== activeIndex && <>
			<h3 className='bplItemTitle'>{sprintf(/* translators: 1: Item label, e.g. Card. 2: Item number. */ __('%1$s %2$d:'), itemLabel, activeIndex + 1)}</h3>

			<ItemSettings {...itemProps} index={activeIndex} />

			<ItemAction items={items} index={activeIndex} duplicateItem={duplicateItem} removeItem={removeItem} />
		</>}

		{'all' === design && items.map((item, index) => {
			return <PanelBody key={index} className='bPlPanelBody itemPanelBody' title={sprintf(/* translators: 1: Item label, e.g. Card. 2: Item number. */ __('%1$s %2$d:'), itemLabel, index + 1)} initialOpen={activeIndex ? activeIndex === index ? true : false : 0 !== index ? false : true}>
				<ItemSettings {...itemProps} index={index} />

				<ItemAction items={items} index={index} duplicateItem={duplicateItem} removeItem={removeItem} />
			</PanelBody>
		})}

		{'sortable' === design && <Sortable {...props} />}

		<Flex justify='center' className='addItem mt15'>
			<Button variant='primary' label={sprintf( /* translators: %s: Item label, e.g. Slide. */ __('Add New %s'), itemLabel)} onClick={addNewItem}>
				<Dashicon icon='plus' />
				{sprintf( /* translators: %s: Item label, e.g. Slide. */ __('Add New %s'), itemLabel)}
			</Button>
		</Flex>
	</>
};
export default ItemsPanel;

const ItemAction = ({ items, index, duplicateItem, removeItem }) => <PanelRow className='itemAction mt20 mb15'>
	<Button className='duplicateItem' label={__('Duplicate')} onClick={e => duplicateItem(e, index)}>
		{copyIcon}{__('Duplicate')}
	</Button>

	{1 < items?.length && <Button className='removeItem' label={__('Remove')} onClick={e => removeItem(e, index)}>
		<Dashicon icon='no' />
		{__('Remove')}
	</Button>}
</PanelRow>